    #[DataProvider('sseCases')]
    public function testSse(array $case): void
    {
        $raw = base64_decode(self::text($case['raw_base64']), true);
        self::assertIsString($raw);
        $expected = self::arr(self::arr($case['expect'])['events']);
        $splits = [[$raw], str_split($raw, 1), str_split($raw, 3), str_split($raw, 7)];
        if (isset($case['chunks_base64'])) {
            $splits[] = array_map(static fn ($c): string => (string) base64_decode(self::text($c), true), self::arr($case['chunks_base64']));
        }
        foreach ($splits as $chunks) {
            $parser = new SseParser();
            $events = [];
            foreach ($chunks as $chunk) {
                foreach ($parser->feed($chunk) as $event) {
                    $seen = ['event' => $event->event, 'data' => $event->data, 'id' => $event->id];
                    if ($event->retry !== null) {
                        $seen['retry'] = $event->retry;
                    }
                    $events[] = $seen;
                }
            }
            self::assertSame(self::json($expected), self::json($events), 'split into ' . count($chunks) . ' chunks');
        }
    }

