    /**
     * A stream call repeated with the same Idempotency-Key after its turn
     * finished is answered with the stored ChatTurnResult as JSON: the
     * stream must yield the events of that turn, not a DecodeError.
     *
     * @param array<string, mixed> $case
     */
    #[DataProvider('chatStreamReplayCases')]
    public function testChatStreamReplay(array $case): void
    {
        $expect = self::arr($case['expect']);
        self::assertIsInt($case['status']);
        $headers = [];
        foreach (self::arr($case['headers']) as $name => $value) {
            $headers[(string) $name] = self::text($value);
        }
        $spec = ['status' => $case['status'], 'headers' => $headers, 'body' => self::json($case['body'])];
        if (($expect['decode_error'] ?? false) === true) {
            $this->enqueue($spec);
            try {
                $this->client()->chat->createStream(new ChatMessageRequest(message: 'q'));
                self::fail('a JSON answer that is not a replay is not a stream');
            } catch (DecodeError $e) {
                self::assertSame($case['status'], $e->status);
            }

            return;
        }
        $this->enqueue($spec, $spec, $spec);
        $client = $this->client();
        $open = static fn (): ChatStream => $client->chat->createStream(new ChatMessageRequest(message: 'q'));
        self::checkChatStream($expect, $open, true);
    }

    /**
     * @param array<string, mixed>   $expect
     * @param \Closure(): ChatStream $open
     */
    private static function checkChatStream(array $expect, \Closure $open, bool $finished): void
    {
        if ($expect['error'] === null && !$finished) {
            // The turn never finished: its events are delivered, but accumulate() refuses to
            // present the partial text as an answer.
            self::assertIsInt($expect['event_count']);
            self::assertCount($expect['event_count'], iterator_to_array($open(), false));
            try {
                $open()->accumulate(throwOnError: false);
                self::fail('a stream without a done event is not a finished turn');
            } catch (DecodeError $e) {
                self::assertStringContainsString('ended before completion', $e->getMessage());
                self::assertSame($expect['text'], $e->body);
            }

            return;
        }

        $result = $open()->accumulate(throwOnError: false);
        self::assertSame($expect['dialog_id'], $result->dialogId);
        self::assertSame($expect['turn_no'], $result->turnNo);
        self::assertSame($expect['text'], $result->text);
        self::assertSame($expect['stop_reason'], $result->stopReason);
        self::assertSame($expect['cost_tiyn'], $result->costTiyn);
        self::assertSame($expect['choice_id'], $result->choiceId);
        self::assertCount($expect['event_count'], $result->events);
        if ($expect['usage'] === null) {
            self::assertNull($result->usage);
        } else {
            $usage = self::arr(json_decode(self::json($result->usage), true));
            foreach (self::arr($expect['usage']) as $name => $value) {
                self::assertSame($value, $usage[$name] ?? null, 'usage.' . $name);
            }
        }
        if (isset($expect['event_types'])) {
            $types = array_map(
                static fn ($event): mixed => $event instanceof ChatEventUnknown
                    ? $event->type
                    : self::arr(json_decode(self::json($event), true))['type'],
                $result->events,
            );
            self::assertSame($expect['event_types'], $types);
        }
        if ($expect['error'] === null) {
            self::assertNull($result->error);
            self::assertSame($expect['text'], $open()->accumulate()->text);

            return;
        }
        $wanted = self::arr($expect['error']);
        $error = $result->error;
        self::assertNotNull($error);
        self::assertSame(self::ERROR_CLASSES[self::text($wanted['type'])], $error::class);
        self::assertSame($wanted['type'], $error->type);
        self::assertSame($wanted['code'], $error->errorCode);
        self::assertSame($wanted['message'], $error->apiMessage);
        self::assertSame($wanted['request_id'], $error->requestId);
        self::assertSame(self::canonical(self::json((object) self::arr($wanted['extra']))), self::canonical(self::json((object) $error->extra)));
        try {
            $open()->accumulate();
            self::fail('accumulate() must raise the error event by default');
        } catch (ApiError $raised) {
            self::assertSame($error::class, $raised::class);
            self::assertSame($wanted['code'], $raised->errorCode);
        }
    }

