    /**
     * @return \Generator<string, array{0: array<string, mixed>}>
     */
    private static function cases(string $section, ?string $list): \Generator
    {
        $cases = self::fixture('vectors')[$section] ?? null;
        if ($list !== null && is_array($cases)) {
            $cases = $cases[$list] ?? null;
        }
        if (!is_array($cases) || $cases === []) {
            throw new \RuntimeException(sprintf('The vectors have no cases in %s%s', $section, $list === null ? '' : '.' . $list));
        }
        foreach (array_values($cases) as $index => $case) {
            if (!is_array($case)) {
                throw new \RuntimeException('A vector case is not an object');
            }
            /** @var array<string, mixed> $case */
            $name = is_string($case['name'] ?? null) ? $case['name'] : 'status ' . self::json($case['status'] ?? $index);
            yield sprintf('#%d %s', $index, $name) => [$case];
        }
    }

    /**
     * @return array<array-key, mixed>
     */
    private static function arr(mixed $value): array
    {
        if ($value instanceof \stdClass) {
            // An empty JSON object of the vectors.
            $value = get_object_vars($value);
        }
        self::assertIsArray($value);

        return $value;
    }

    private static function text(mixed $value): string
    {
        self::assertIsString($value);

        return $value;
    }
